// Required by code generated by the upstream `#[instrument]` macro.
extern crate miden_node_tracing as tracing;

use clap::Parser;
use clap::error::ErrorKind;
use commands::Command;

mod admin;
mod commands;

const LOG_TARGET: &str = "user::miden-node";

// COMMANDS
// ================================================================================================

/// Operate and maintain a Miden node.
#[derive(Parser, Debug)]
#[command(version)]
pub struct Cli {
    #[command(subcommand)]
    pub command: Command,
}

// MAIN
// ================================================================================================

fn parse_cli() -> Cli {
    match Cli::try_parse() {
        Ok(cli) => cli,
        // We inject custom section descriptions into help output to improve readability.
        Err(err) if err.kind() == ErrorKind::DisplayHelp => {
            print!("{}", commands::section::inject_section_descriptions(err.to_string()));
            std::process::exit(err.exit_code());
        },
        Err(err) => err.exit(),
    }
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let cli = parse_cli();

    // Configure tracing with optional OpenTelemetry exporting support.
    let _otel_guard = miden_node_tracing::setup_tracing(cli.command.open_telemetry())?;

    let result = miden_node_utils::shutdown::run_with_shutdown("miden-node", |shutdown| {
        cli.command.execute(shutdown)
    })
    .await;

    // Failures that end the process, such as a store that cannot be loaded at startup, are
    // otherwise only printed to stderr when `main` returns, and never reach the tracing layers.
    if let Err(err) = &result {
        miden_node_tracing::error!(err, target: LOG_TARGET, "Node exited with an error");
    }
    result
}
